                        diego: 'defensive',
                        sofia: 'anxious',
                        carlos: 'invisible',
                        ana: 'ignored',
                        mateo: 'compliant',
                        priya: 'withdrawing',
                        roberto: 'disengaged'
                    },
                    decisionsMade: [],
                    currentMeeting: 1,
                    // Contract with express/results_utils.php :: express_resolveDomainScore()
                    // — it reads domainState.performance.overallScore, then a top-level score.
                    score: 0,
                    performance: { overallScore: 0, grade: 'F' }
                };
            } else {
                const _ds = state.domainState;
                if (_ds.score === undefined) _ds.score = 0;
                if (!_ds.performance) _ds.performance = { overallScore: _ds.score || 0, grade: this._grade(_ds.score || 0) };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { selectedOption: null };
            }
            this._bindOnce();
            this._render(state);
        }

        validateDecisions(decisions) {
            // The choice is read from the radio group on screen: its value is the model index.
            const checked = document.querySelector('input[name="decisionOption"]:checked');
            const st = this._state();
            const shown = this._shownMeeting(st);
            const meeting = shown ? this.MEETINGS[shown - 1] : null;
            const value = checked ? parseInt(checked.value, 10) : NaN;
            if (!meeting || !(value >= 0 && value < meeting.options.length)) {
                window.mySimulation.uiManager.showNotification(this._tr('select_option_warning'), 'warning');
                return false;
            }
            this.selectedOption = value;
            decisions.selectedOption = value;
            return true;
        }

        calculateResults(state) {
            const meeting = this.MEETINGS[state.currentPeriod - 1];
            const option = meeting.options[state.decisions.selectedOption];

            const safetyDelta = option.safetyDelta;
            const trustDelta = option.trustDelta;

            state.domainState.psychologicalSafety = Math.max(0, Math.min(10,
                state.domainState.psychologicalSafety + safetyDelta));
            state.domainState.trustIndex = Math.max(0, Math.min(10,
                state.domainState.trustIndex + trustDelta));

            const innovationBoost = safetyDelta > 1.0 ? 3 : safetyDelta > 0 ? 1 : safetyDelta < 0 ? -1 : 0;
            state.domainState.innovationOutput = Math.max(0,
                state.domainState.innovationOutput + innovationBoost);

            const launchBoost = (safetyDelta + trustDelta) * 2;
            state.domainState.launchProbability = Math.max(0, Math.min(100,
                state.domainState.launchProbability + launchBoost));

            state.domainState.safetyHistory.push(state.domainState.psychologicalSafety);
            state.domainState.trustHistory.push(state.domainState.trustIndex);
            state.domainState.innovationHistory.push(state.domainState.innovationOutput);

            this._updateMemberStates(state, safetyDelta);
            state.domainState.decisionsMade.push({
                meeting: state.currentPeriod,
                option: state.decisions.selectedOption,
                safetyDelta: safetyDelta,
                trustDelta: trustDelta
            });

            this.selectedOption = null;

            // Composite 0-100 score, recomputed every meeting and written into
            // domainState in BOTH shapes the PHP grading layer accepts.
            const score = this._computeScore(state.domainState);
            state.domainState.score = score;
            state.domainState.performance = { overallScore: score, grade: this._grade(score) };

            // The screen is repainted once the round is in the history (see _shownMeeting):
            // the next meeting, the response to this one, the roster and, at the end, the final panel.
            setTimeout(() => this._render(this._state() || state), 0);

            return {
                period: state.currentPeriod,
                meeting: meeting.id,
                safetyScore: state.domainState.psychologicalSafety,
                trustScore: state.domainState.trustIndex,
                innovationOutput: state.domainState.innovationOutput,
                launchProbability: state.domainState.launchProbability,
                safetyDelta: safetyDelta,
                trustDelta: trustDelta,
                score: score,
                overallScore: score,
                finalScore: state.currentPeriod >= (state.maxPeriods || 4) ? score : undefined
            };
        }

        _grade(score) {
            if (score >= 85) return 'A';
            if (score >= 70) return 'B';
            if (score >= 55) return 'C';
            if (score >= 40) return 'D';
            return 'F';
        }

        /**
         * Weights follow the debrief narrative: safety is the headline construct,
         * trust the leading indicator, innovation and launch the lagging outcomes.
         */
        _scoreParts(ds) {
            const safety = Math.max(0, Math.min(10, ds.psychologicalSafety || 0));
            const trust = Math.max(0, Math.min(10, ds.trustIndex || 0));
            const innovation = Math.max(0, Math.min(100, (ds.innovationOutput || 0) * 10));
            const launch = Math.max(0, Math.min(100, ds.launchProbability || 0));
            return {
                safety: (safety * 10) * 0.40,
                trust: (trust * 10) * 0.25,
                innovation: innovation * 0.15,
                launch: launch * 0.20
            };
        }

        _computeScore(ds) {
            const p = this._scoreParts(ds);
            return Math.round(p.safety + p.trust + p.innovation + p.launch);
        }

        _updateMemberStates(state, safetyDelta) {
            const members = state.domainState.memberStates;

            if (safetyDelta > 1.0) {
                if (members.valentina === 'guarded') members.valentina = 'engaged';
                if (members.diego === 'defensive') members.diego = 'open';
                if (members.carlos === 'invisible') members.carlos = 'contributing';
                if (members.ana === 'ignored') members.ana = 'heard';
                if (members.priya === 'withdrawing') members.priya = 'committed';
                if (members.roberto === 'disengaged') members.roberto = 're-engaged';
            } else if (safetyDelta > 0) {
                if (members.sofia === 'anxious') members.sofia = 'confident';
                if (members.mateo === 'compliant') members.mateo = 'candid';
            } else if (safetyDelta < -1.0) {
                if (members.diego === 'open' || members.diego === 'defensive') members.diego = 'defensive';
                if (members.priya === 'committed' || members.priya === 'withdrawing') members.priya = 'withdrawing';
                if (members.roberto === 're-engaged' || members.roberto === 'disengaged') members.roberto = 'disengaged';
            }
        }

        // ---- rendering (v1.2.0): everything the adapter writes is rebuilt from the state ----
        _bindOnce() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            var repaint = function () {
                var st = self._state();
                if (st && st.domainState && st.domainState.memberStates) { self._render(st); }
            };
            var box = document.getElementById('decisionOptions');
            if (box) {
                box.addEventListener('change', function (ev) {
                    var t = ev.target;
                    if (!t || t.name !== 'decisionOption') { return; }
                    self.selectedOption = parseInt(t.value, 10);
                    self._markSelected();
                });
            }
            document.addEventListener('express:langchanged', function () { setTimeout(repaint, 0); });
            var hook = function () {
                var fw = window.mySimulation;
                if (!fw || !fw.eventBus || typeof fw.eventBus.on !== 'function') { return false; }
                fw.eventBus.on('language:changed', function () { setTimeout(repaint, 0); });
                fw.eventBus.on('period:undone', function () { setTimeout(repaint, 0); });
                fw.eventBus.on('period:submitted', function () { setTimeout(repaint, 0); });
                fw.eventBus.on('state:loaded', function () { setTimeout(repaint, 0); });
                return true;
            };
            if (!hook()) { setTimeout(hook, 0); }
        }

        _markSelected() {
            var cards = document.querySelectorAll('#decisionOptions .psychsafety-sim-option-btn');
            for (var i = 0; i < cards.length; i++) {
                var input = cards[i].querySelector('input[name="decisionOption"]');
                if (input && input.checked) { cards[i].classList.add('selected'); } else { cards[i].classList.remove('selected'); }
            }
        }

        _render(state) {
            if (!state || !state.domainState) { return; }
            this._lastState = state;
            var shown = this._shownMeeting(state);
            var scenarioPanel = document.querySelector('.psychsafety-sim-scenario-panel');
            var decisionPanel = document.querySelector('.psychsafety-sim-decision-panel');
            if (shown) {
                var meeting = this.MEETINGS[shown - 1];
                var badge = document.getElementById('meetingBadge');
                var title = document.getElementById('scenarioTitle');
                var text = document.getElementById('scenarioText');
                var context = document.getElementById('decisionContext');
                if (badge) { badge.textContent = this._tr('meeting_label') + ' ' + meeting.id; }
                if (title) { title.removeAttribute('data-i18n'); title.textContent = this._loc(meeting, 'title'); }
                if (text) { text.textContent = this._loc(meeting, 'description'); }
                if (context) { context.textContent = this._loc(meeting, 'decisionContext'); }
                this._renderOptions(meeting);
                if (scenarioPanel) { scenarioPanel.style.display = ''; }
                if (decisionPanel) { decisionPanel.style.display = ''; }
            } else {
                // complete run: no live decision, the final panel takes its place
                if (decisionPanel) { decisionPanel.style.display = 'none'; }
                if (scenarioPanel) { scenarioPanel.style.display = 'none'; }
            }
            this._renderStatic();
            this._renderFeedback(state);
            this._updateTeamGrid(state);
            if (!shown) { this._showFinalResults(state); }
            else {
                var fp = document.getElementById('finalPanel');
                if (fp) { fp.style.display = 'none'; }
            }
        }

        _renderOptions(meeting) {
            var box = document.getElementById('decisionOptions');
            if (!box) { return; }
            // The five radio inputs are kept for the whole run and only their value and text change:
            // the value is the model index of the option shown at that screen position.
            var labels = box.querySelectorAll('label.psychsafety-sim-option-btn');
            var pos;
            if (labels.length < 5) {
                var html = '';
                for (pos = 0; pos < 5; pos++) {
                    html += '<label class="psychsafety-sim-option-btn" for="opt' + pos + '">' +
                        '<input type="radio" class="psychsafety-sim-option-radio" name="decisionOption" id="opt' + pos + '" value="' + pos + '">' +
                        '<span class="psychsafety-sim-option-text"></span></label>';
                }
                box.innerHTML = html;
                labels = box.querySelectorAll('label.psychsafety-sim-option-btn');
            }
            var st = this._state();
            var sig = meeting.id + '|' + (st && st.gameId ? st.gameId : '');
            var sameMeeting = sig === this._optionsSig;
            this._optionsSig = sig;
            var order = this._optionOrder(meeting.id, meeting.options.length);
            for (pos = 0; pos < labels.length; pos++) {
                var input = labels[pos].querySelector('input[name="decisionOption"]');
                var span = labels[pos].querySelector('.psychsafety-sim-option-text');
                if (!input || !span) { continue; }
                if (pos < order.length) {
                    var opt = meeting.options[order[pos]];
                    if (input.value !== String(order[pos])) { input.value = String(order[pos]); }
                    var text = this._loc(opt, 'text');
                    if (span.textContent !== text) { span.textContent = text; }
                    input.disabled = false;
                    labels[pos].style.display = '';
                } else {
                    input.checked = false;
                    input.disabled = true;
                    span.textContent = '';
                    labels[pos].style.display = 'none';
                }
                if (!sameMeeting) { input.checked = false; }
            }
            if (!sameMeeting) { this.selectedOption = null; }
            this._markSelected();
        }

        _renderStatic() {
            // text the view carries in English only
            var lang = this._lang();
            var keys = Object.keys(this.TEAM_MEMBERS);
            for (var i = 0; i < keys.length; i++) {
                var el = document.getElementById('member-' + keys[i]);
                var roleEl = el ? el.querySelector('.psychsafety-sim-member-role') : null;
                var m = this.TEAM_MEMBERS[keys[i]];
                if (roleEl) { roleEl.textContent = lang === 'es' ? m.role_es : m.role; }
            }
            var canvas = document.getElementById('safetyChart');
            if (canvas) { canvas.setAttribute('role', 'img'); canvas.setAttribute('aria-label', this._tr('chart_alt')); }
        }

        _lastDecision(state) {
            var made = state && state.domainState && state.domainState.decisionsMade;
            return Array.isArray(made) && made.length ? made[made.length - 1] : null;
        }

        _renderFeedback(state) {
            var panel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            var impactSummary = document.getElementById('impactSummary');
            var header = panel ? panel.querySelector('.psychsafety-sim-feedback-header') : null;
            if (!panel || !feedbackText || !impactSummary) { return; }
            var last = this._lastDecision(state);
            var n = state && Array.isArray(state.history) ? state.history.length : 0;
            if (!last || !n) { panel.style.display = 'none'; return; }
            var meeting = this.MEETINGS[last.meeting - 1];
            var option = meeting ? meeting.options[last.option] : null;
            if (!option) { panel.style.display = 'none'; return; }
            if (header) { header.removeAttribute('data-i18n'); header.textContent = this._tr('consequence_heading') + ' — ' + this._tr('meeting_label') + ' ' + meeting.id; }
            feedbackText.textContent = this._loc(option, 'feedback');
            var sign = function (v) { return v > 0 ? '+' : ''; };
            var cls = function (v) { return v > 0 ? 'positive' : v < 0 ? 'negative' : 'neutral'; };
            impactSummary.innerHTML =
                '<span class="psychsafety-sim-impact-item ' + cls(last.safetyDelta) + '">' + this._esc(this._tr('safety_label')) + ': ' + sign(last.safetyDelta) + this._num(last.safetyDelta) + '</span> ' +
                '<span class="psychsafety-sim-impact-item ' + cls(last.trustDelta) + '">' + this._esc(this._tr('trust_label')) + ': ' + sign(last.trustDelta) + this._num(last.trustDelta) + '</span>';
            panel.style.display = 'block';
        }

        _archetype(safety) {
            for (var i = 0; i < this.ARCHETYPES.length; i++) { if (safety >= this.ARCHETYPES[i].min) { return this.ARCHETYPES[i]; } }
            return this.ARCHETYPES[this.ARCHETYPES.length - 1];
        }

        _showFinalResults(state) {
            const panel = document.getElementById('finalPanel');
            const archetypeDisplay = document.getElementById('archetypeDisplay');
            const finalMetrics = document.getElementById('finalMetrics');
            const teamOutcomes = document.getElementById('teamOutcomes');
            const lang = this._lang();

            if (!panel) return;

            const ds = state.domainState;
            const safety = ds.psychologicalSafety;
            const archetype = this._archetype(safety);

            if (archetypeDisplay) {
                archetypeDisplay.textContent = this._loc(archetype, 'name');
                archetypeDisplay.style.color = safety >= 7.5 ? '#34d399' : safety >= 5.5 ? '#60a5fa' : safety >= 4.0 ? '#fbbf24' : safety >= 2.5 ? '#f87171' : '#ef4444';
            }

            if (finalMetrics) {
                var metric = (label, value) => '<div class="psychsafety-sim-final-metric">' +
                    '<div class="psychsafety-sim-final-metric-label">' + this._esc(label) + '</div>' +
                    '<div class="psychsafety-sim-final-metric-value">' + this._esc(value) + '</div></div>';
                finalMetrics.innerHTML =
                    metric(this._tr('final_safety_label'), this._num(safety) + '/10') +
                    metric(this._tr('trust_label'), this._num(ds.trustIndex) + '/10') +
                    metric(this._tr('innovation_label'), String(ds.innovationOutput)) +
                    metric(this._tr('launch_label'), Math.round(ds.launchProbability) + '%');
            }

            if (teamOutcomes) {
                teamOutcomes.innerHTML = Object.keys(this.TEAM_MEMBERS).map((key) => {
                    const member = this.TEAM_MEMBERS[key];
                    const outcomeText = this._getMemberOutcome(key, ds.memberStates[key], lang);
                    return '<div class="psychsafety-sim-team-outcome">' +
                        '<div class="psychsafety-sim-team-outcome-name">' + this._esc(member.name) + ' — ' + this._esc(lang === 'es' ? member.role_es : member.role) + '</div>' +
                        '<div class="psychsafety-sim-team-outcome-text">' + this._esc(outcomeText) + '</div></div>';
                }).join('');
            }

            panel.style.display = 'block';
        }

        _getMemberOutcome(memberKey, state, lang) {
            const outcomes = {
                valentina: {
                    engaged: lang === 'es' ?
                        'Esta es la primera vez en 14 meses que siento que mis ideas realmente importan aquí. Me quedé hasta medianoche trabajando en la especificación de integración — no porque tuviera que hacerlo, sino porque quería.' :
                        'This is the first time in 14 months I have felt like my ideas actually matter here. I stayed up until midnight working on the integration spec — not because I had to, but because I wanted to.',
                    guarded: lang === 'es' ?
                        'He comenzado a actualizar mi CV. Tengo buenas ideas. Me gustaría trabajar en un lugar donde sean escuchadas.' :
                        'I have started updating my CV. I have good ideas. I would like to work somewhere they get heard.'
                },
                diego: {
                    open: lang === 'es' ?
                        'Nunca pensé que podría admitir un error sin sentir que mi carrera terminaba. Este equipo es diferente. Estoy comprometido a hacer que este lanzamiento sea exitoso.' :
                        'I never thought I could admit a mistake without feeling like my career was over. This team is different. I am committed to making this launch successful.',
                    defensive: lang === 'es' ?
                        'Estoy buscando activamente otras oportunidades. No puedo trabajar en un entorno donde un error te marca para siempre.' :
                        'I am actively looking for other opportunities. I cannot work in an environment where one mistake marks you forever.'
                },
                carlos: {
                    contributing: lang === 'es' ?
                        'Por primera vez, alguien dijo “esta es la idea de Carlos” en una reunión. Casi no sé qué hacer con eso, pero quiero más.' :
                        'For the first time, someone said “this is Carlos’s idea” in a meeting. I almost do not know what to do with that, but I want more.',
                    invisible: lang === 'es' ?
                        'Sigo enviando análisis detallados. Nadie los menciona. He dejado de asistir a las reuniones de equipo.' :
                        'I still send detailed analysis. No one mentions them. I have stopped attending team meetings.'
                },
                ana: {
                    heard: lang === 'es' ?
                        'Mi trabajo de identificación de riesgos finalmente se toma en serio. He comenzado a compartir hallazgos proactivamente en lugar de esperar a que me pregunten.' :
                        'My risk identification work is finally taken seriously. I have started sharing findings proactively instead of waiting to be asked.',
                    ignored: lang === 'es' ?
                        'Documentaré todo por correo electrónico desde ahora. No confiaré en que las preocupaciones verbales sean registradas.' :
                        'I will document everything by email from now on. I do not trust that verbal concerns will be recorded.'
                },
                priya: {
                    committed: lang === 'es' ?
                        'Cancelé mi entrevista con otra empresa. Esta cultura es rara y valiosa. Quiero ayudar a construirla.' :
                        'I canceled my interview with another company. This culture is rare and valuable. I want to help build it.',
                    withdrawing: lang === 'es' ?
                        'He solicitado transferencia a otro equipo. No puedo trabajar en un lugar donde guardar silencio es más seguro que hablar.' :
                        'I have requested a transfer to another team. I cannot work somewhere where silence is safer than speaking up.'
                },
                roberto: {
                    're-engaged': lang === 'es' ?
                        'Pensé que este sería otro trabajo donde hacer el mínimo era la estrategia correcta. Me equivoqué. Tengo ideas para la versión 4.0.' :
                        'I thought this would be another job where minimum viable effort was the right strategy. I was wrong. I have ideas for version 4.0.',
                    disengaged: lang === 'es' ?
                        'Estoy aquí físicamente. Eso es todo lo que pueden esperar de mí.' :
                        'I am here physically. That is all you can expect from me.'
                }
            };

            const memberOutcomes = outcomes[memberKey];
            if (memberOutcomes && memberOutcomes[state]) {
                return memberOutcomes[state];
            }

            return lang === 'es' ?
                'Continúa observando la dinámica del equipo, evaluando si es seguro contribuir plenamente.' :
                'Continues observing team dynamics, evaluating whether it is safe to fully contribute.';
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('safetyDisplay', 'domainState.psychologicalSafety',
                (v) => v.toFixed(1) + '/10');
            uiManager.bind('trustDisplay', 'domainState.trustIndex',
                (v) => v.toFixed(1) + '/10');
            uiManager.bind('innovationDisplay', 'domainState.innovationOutput');
            uiManager.bind('launchDisplay', 'domainState.launchProbability',
                (v) => Math.round(v) + '%');

            this._bindOnce();
        }

        _memberLabel(key, stateValue) {
            const member = this.TEAM_MEMBERS[key];
            var label = stateValue.charAt(0).toUpperCase() + stateValue.slice(1);
            // the state keys are the lowercased English words in member.states: find the tier
            // (low, mid, high) and read the same tier from member.states_es when in Spanish
            if (this._lang() === 'es' && member && member.states && member.states_es) {
                var tiers = ['low', 'mid', 'high'];
                for (var i = 0; i < tiers.length; i++) {
                    if (member.states[tiers[i]] && member.states[tiers[i]].toLowerCase() === stateValue.toLowerCase()) {
                        label = member.states_es[tiers[i]];
                        break;
                    }
                }
            }
            return label;
        }

        _updateTeamGrid(state) {
            const grid = document.getElementById('teamGrid');
            if (!grid || !state.domainState.memberStates) return;

            Object.keys(this.TEAM_MEMBERS).forEach((key) => {
                const memberEl = document.getElementById('member-' + key);
                if (memberEl) {
                    const stateValue = state.domainState.memberStates[key];
                    const stateEl = memberEl.querySelector('.psychsafety-sim-member-state');
                    if (stateEl) {
                        stateEl.dataset.state = stateValue;
                        stateEl.textContent = this._memberLabel(key, stateValue);
                    }
                }
            });
        }

        getChartConfig() {
            return {
                safetyChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._tr('safety_label'),
                                data: [],
                                borderColor: '#f472b6',
                                backgroundColor: 'rgba(244,114,182,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3
                            },
                            {
                                label: this._tr('trust_label'),
                                data: [],
                                borderColor: '#60a5fa',
                                backgroundColor: 'rgba(96,165,250,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: {
                                display: true,
                                text: this._tr('chart_team_dynamics_title'),
                                color: '#e8eaf6'
                            },
                            legend: {
                                labels: { color: '#94a3b8' }
                            }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 10,
                                ticks: { color: '#94a3b8' },
                                grid: { color: 'rgba(255,255,255,0.1)' }
                            },
                            x: {
                                ticks: { color: '#94a3b8' },
                                grid: { color: 'rgba(255,255,255,0.1)' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = (state && state.domainState) || {};
            const safetyHistory = ds.safetyHistory || [];
            const trustHistory = ds.trustHistory || [];
            // the first point is the opening state, before any meeting
            const labels = safetyHistory.map((_, i) => (i === 0 ? this._tr('chart_start') : 'M' + i));
            return {
                safetyChart: {
                    labels: labels,
                    datasets: [
                        { data: safetyHistory },
                        { data: trustHistory }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.meeting', label: 'Meeting', i18nKey: 'col_meeting' },
                { key: 'results.safetyScore', label: 'Safety Score', i18nKey: 'col_safety', formatter: (v) => v.toFixed(1) },
                { key: 'results.trustScore', label: 'Trust Index', i18nKey: 'col_trust', formatter: (v) => v.toFixed(1) },
                { key: 'results.innovationOutput', label: 'Innovation', i18nKey: 'col_innovation' },
                { key: 'results.launchProbability', label: 'Launch %', i18nKey: 'col_launch', formatter: (v) => Math.round(v) + '%' }
            ];
        }

        // ---- debrief (v1.2.0): built from what this run did ----
        // The plays the debrief names, detected from the decisions made. Each entry: meeting, model option.
        _namedPlays() {
            return [
                { key: 'm1_agenda', meeting: 1, option: 0 },
                { key: 'm2_rebuke', meeting: 2, option: 0 },
                { key: 'm2_pivot', meeting: 2, option: 3 },
                { key: 'm3_letgo', meeting: 3, option: 0 },
                { key: 'm4_confirm', meeting: 4, option: 0 }
            ];
        }

        _runFacts(history) {
            const last = history[history.length - 1] || {};
            const final = last.results || {};
            const ds = last.domainState || {};
            const made = [];
            for (var i = 0; i < history.length; i++) {
                var h = history[i] || {}, r = h.results || {};
                var opt = h.decisions && h.decisions.selectedOption;
                var hd = h.domainState && h.domainState.decisionsMade;
                if (Array.isArray(hd) && hd.length > i && hd[i]) { opt = hd[i].option; }
                made.push({ meeting: r.meeting || (i + 1), option: opt, safetyDelta: Number(r.safetyDelta) || 0, trustDelta: Number(r.trustDelta) || 0, score: r.score });
            }
            const members = ds.memberStates || {};
            const unmoved = [], keys = Object.keys(this.OPENING_STATES);
            for (var k = 0; k < keys.length; k++) { if (!members[keys[k]] || members[keys[k]] === this.OPENING_STATES[keys[k]]) { unmoved.push(this.TEAM_MEMBERS[keys[k]].name); } }
            // turning point: the meeting that cost the most safety; when none cost any, the one that moved it most
            var turn = null, m;
            for (m = 0; m < made.length; m++) { if (made[m].safetyDelta < 0 && (!turn || made[m].safetyDelta < turn.safetyDelta)) { turn = made[m]; } }
            var negative = !!turn;
            if (!turn) { for (m = 0; m < made.length; m++) { if (!turn || made[m].safetyDelta > turn.safetyDelta) { turn = made[m]; } } }
            return { final: final, ds: ds, made: made, unmoved: unmoved, improved: keys.length - unmoved.length, members: keys.length, turn: turn, turnNegative: negative };
        }

        _fill(key, vars) {
            var s = this._tr(key);
            Object.keys(vars || {}).forEach(function (name) { s = s.split('{' + name + '}').join(String(vars[name])); });
            return s;
        }

        _signed(v) { return (v > 0 ? '+' : '') + this._num(v); }

        _insights(facts) {
            const out = [];
            const made = facts.made;
            // the plays this run made, named
            const plays = this._namedPlays();
            for (var i = 0; i < plays.length; i++) {
                var p = plays[i], hit = null;
                for (var j = 0; j < made.length; j++) { if (made[j].meeting === p.meeting && made[j].option === p.option) { hit = made[j]; } }
                if (hit) { out.push(this._fill('ins_' + p.key, { ds: this._signed(hit.safetyDelta), dt: this._signed(hit.trustDelta) })); }
            }
            var sSum = 0, tSum = 0, drops = 0;
            for (var k = 0; k < made.length; k++) { sSum += made[k].safetyDelta; tSum += made[k].trustDelta; if (made[k].safetyDelta < 0) { drops++; } }
            out.push(this._fill('ins_two_indices', { ds: this._signed(Math.round(sSum * 10) / 10), dt: this._signed(Math.round(tSum * 10) / 10), s: this._num(facts.final.safetyScore), t: this._num(facts.final.trustScore) }));
            if (facts.unmoved.length) { out.push(this._fill('ins_roster_some', { n: facts.improved, total: facts.members, names: facts.unmoved.join(', ') })); }
            else { out.push(this._fill('ins_roster_all', { total: facts.members })); }
            out.push(this._fill('ins_outputs', { ideas: facts.final.innovationOutput, launch: Math.round(facts.final.launchProbability), ideas0: this.START.ideas, launch0: this.START.launch }));
            return out.slice(0, 5);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};

            const facts = this._runFacts(history);
            const final = facts.final;
            const archetype = this._archetype(final.safetyScore);
            const finalScore = (final.score != null) ? final.score : (facts.ds.score || 0);
            const grade = this._grade(finalScore);

            return {
                finalScore: finalScore,
                overallScore: finalScore,
                totalScore: finalScore,
                score: finalScore,
                composite: finalScore,
                grade: grade,
                // the verdict is the grade band of the score; the archetype is a second reading, from final safety
                performance: 'grade_' + grade.toLowerCase(),
                performanceKey: 'grade_' + grade.toLowerCase(),
                performanceLabel: this._fill('grade_label', { grade: grade }),
                finalSafety: final.safetyScore,
                finalTrust: final.trustScore,
                finalInnovation: final.innovationOutput,
                finalLaunch: final.launchProbability,
                archetypeKey: archetype.key,
                archetype: this._loc(archetype, 'name'),
                membersImproved: facts.improved,
                insights: this._insights(facts)
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            const st = this._state();
            const history = st && Array.isArray(st.history) ? st.history : [];
            if (!history.length) {
                return '<div class="psychsafety-cm"><p>' + this._esc(this._tr('cm_none')) + '</p></div>';
            }
            const facts = this._runFacts(history);
            const final = facts.final;
            const score = (final.score != null) ? final.score : (facts.ds.score || 0);
            const grade = this._grade(score);
            const archetype = this._archetype(final.safetyScore);
            const parts = this._scoreParts({ psychologicalSafety: final.safetyScore, trustIndex: final.trustScore, innovationOutput: final.innovationOutput, launchProbability: final.launchProbability });
            const e = (s) => this._esc(s);
            const kpi = (label, from, to) => '<div class="psychsafety-cm-kpi"><span class="psychsafety-cm-kpi-label">' + e(label) + '</span>' +
                '<span class="psychsafety-cm-kpi-value">' + e(from) + ' → ' + e(to) + '</span></div>';
            const part = (label, value, max) => '<li>' + e(label) + ': <strong>' + e(this._num(value)) + '</strong> / ' + max + '</li>';

            var html = '<div class="psychsafety-cm">';
            html += '<div class="psychsafety-cm-score"><span class="psychsafety-cm-score-num">' + e(score) + '</span><span class="psychsafety-cm-score-max">/100</span>' +
                '<span class="psychsafety-cm-grade">' + e(this._fill('grade_label', { grade: grade })) + '</span></div>';
            html += '<p class="psychsafety-cm-archetype">' + e(this._tr('cm_archetype')) + ': <strong>' + e(this._loc(archetype, 'name')) + '</strong></p>';
            html += '<div class="psychsafety-cm-kpis">' +
                kpi(this._tr('safety_label'), this._num(this.START.safety), this._num(final.safetyScore) + '/10') +
                kpi(this._tr('trust_label'), this._num(this.START.trust), this._num(final.trustScore) + '/10') +
                kpi(this._tr('innovation_label'), String(this.START.ideas), final.innovationOutput + ' ' + this._tr('ideas_month')) +
                kpi(this._tr('launch_label'), this.START.launch + '%', Math.round(final.launchProbability) + '%') +
                '</div>';
            html += '<h4 class="psychsafety-cm-h">' + e(this._tr('cm_parts')) + '</h4><ul class="psychsafety-cm-list">' +
                part(this._tr('safety_label'), parts.safety, 40) + part(this._tr('trust_label'), parts.trust, 25) +
                part(this._tr('innovation_label'), parts.innovation, 15) + part(this._tr('launch_label'), parts.launch, 20) + '</ul>';
            if (facts.turn) {
                var tm = this.MEETINGS[facts.turn.meeting - 1];
                var topt = tm ? tm.options[facts.turn.option] : null;
                html += '<h4 class="psychsafety-cm-h">' + e(this._tr('cm_turning')) + '</h4><p>' +
                    e(this._fill(facts.turnNegative ? 'cm_turn_down' : 'cm_turn_up', { n: facts.turn.meeting, title: tm ? this._loc(tm, 'title') : '', ds: this._signed(facts.turn.safetyDelta), dt: this._signed(facts.turn.trustDelta) })) +
                    (topt ? ' ' + e(this._loc(topt, 'text')) + ' ' + e(this._loc(topt, 'feedback')) : '') + '</p>';
            }
            var list = Array.isArray(summary.insights) && summary.insights.length ? summary.insights : this._insights(facts);
            html += '<h4 class="psychsafety-cm-h">' + e(this._tr('cm_insights')) + '</h4><ul class="psychsafety-cm-list">';
            for (var i = 0; i < list.length; i++) { html += '<li>' + e(list[i]) + '</li>'; }
            html += '</ul>';
            html += '<h4 class="psychsafety-cm-h">' + e(this._tr('cm_questions')) + '</h4><ol class="psychsafety-cm-list">' +
                '<li>' + e(this._tr('cm_q1')) + '</li><li>' + e(this._tr('cm_q2')) + '</li></ol>';
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (state.domainState.psychologicalSafety < 4.0) {
                return this._tr('hint_anxiety');
            }
            if (state.domainState.psychologicalSafety > 7.0 && state.currentPeriod < 4) {
                return this._tr('hint_strong');
            }
            return null;
        }

